import { Button } from "./Button";
import { ArrowRight, Plus } from "lucide-react";

export function Example() {
  return (
    <div className="flex flex-wrap gap-3">
      <Button leadingIcon={<Plus className="h-4 w-4" />}>
        Create Agent
      </Button>
      <Button variant="secondaryGray" trailingIcon={<ArrowRight className="h-4 w-4" />}>
        View Details
      </Button>
      <Button variant="destructive">
        Delete
      </Button>
    </div>
  );
}

developerHandoff.copyScript:
$files = @(
  @{ Path = "src/components/ui/button/Button.tsx"; Url = "https://raw.githubusercontent.com/GurneyK/Design-library/main/src/components/ui/button/Button.tsx" }
)

foreach ($file in $files) {
  $target = Join-Path (Get-Location) $file.Path
  New-Item -ItemType Directory -Force -Path (Split-Path $target) | Out-Null
  Invoke-WebRequest -Uri $file.Url -OutFile $target
}

